import React, { useState } from "react";
import { GoogleLogin } from "@react-oauth/google";
import { useNavigate, Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import SEO from "./SEO";

export default function Login() {
  const { login, googleLogin } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: "", password: "" });
  const [error, setError] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    try {
      await login(form.email, form.password);
      navigate("/");
    } catch (err) {
      setError(err.response?.data?.error || "Login failed");
    }
  };

  return (
    <div className="form-card">
      <SEO title="Log in" path="/login" />
      <h2>Log in</h2>
      <p style={{ color: "var(--muted)", fontSize: 14, marginTop: -4 }}>
        Apne account me wapas aao
      </p>

      <div style={{ margin: "20px 0" }}>
        <GoogleLogin
          onSuccess={async (cred) => {
            try {
              await googleLogin(cred.credential);
              navigate("/");
            } catch {
              setError("Google login failed");
            }
          }}
          onError={() => setError("Google login failed")}
          width="100%"
        />
      </div>
      <div className="divider-text">ya email se login karo</div>

      <form onSubmit={handleSubmit}>
        <label>Email</label>
        <input
          className="form-input"
          type="email"
          value={form.email}
          onChange={(e) => setForm({ ...form, email: e.target.value })}
          required
        />
        <label>Password</label>
        <input
          className="form-input"
          type="password"
          value={form.password}
          onChange={(e) => setForm({ ...form, password: e.target.value })}
          required
        />
        {error && <p className="error-text">{error}</p>}
        <button className="btn btn-block" type="submit">Log in</button>
      </form>

      <p style={{ fontSize: 13, marginTop: 16, textAlign: "center" }}>
        Account nahi hai? <Link to="/register">Register karo</Link>
      </p>
    </div>
  );
}
